contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address[] calldata proposers, address target, uint256 value, bytes calldata data, bytes32 predecessor, bytes32 salt, uint256 delay) public {
        require(proposers.length >= 1, "need a proposer");
        require(proposers[0] == address(this), "first proposer must be this contract");
        require(delay >= c.getMinDelay(), "delay must be at least min delay");

